package com.cvns.security;import java.util.Date;import javax.crypto.SecretKey;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.annotation.PostConstruct;
@Component public class JwtUtils{@Value("${jwt.exp.time}")private long exp;@Value("${jwt.secret.key}")private String key;private SecretKey secret;@PostConstruct public void init(){secret=Keys.hmacShaKeyFor(key.getBytes());}public String generateJwt(CustomUserDetails d){Date now=new Date();return Jwts.builder().subject(d.getUsername()).issuedAt(now).expiration(new Date(now.getTime()+exp)).claim("user_id",d.getUserId()).claim("user_role",d.getUser().getUserRole().name()).signWith(secret).compact();}private Claims claims(String t){return Jwts.parser().verifyWith(secret).build().parseSignedClaims(t).getPayload();}public String getEmail(String t){return claims(t).getSubject();}public boolean validate(String t,CustomUserDetails d){Claims c=claims(t);return c.getSubject().equals(d.getUsername())&&c.getExpiration().after(new Date());}}
